EXEC model.put_semantic_definition 'PROVIDER',N'sidefx:providers',N'ScenarioKernel.NodePlatform',N'{"capabilities":[{"capabilityId":"sda-node-consumer-runtime.v1","conformanceRef":"sha256:e27ed071df2327c3438c498c6125611e13a67ca2af1971fa8381b51327d9f237","implementationRef":"sha256:485f3bd1225baf7846a84f100aac5ffbf43814853613a68db0494827be1e0db6","kind":"consumer-runtime","projectionTarget":"node","provider":"ScenarioKernel.NodePlatform","providesMechanics":["scenario-orchestration","contract-document-reading","canonicalization","schema-admission","authority-resolution","semantic-execution","telemetry-observation","scenario-invocation","transition-binding-projection","interface-delivery","runtime-projection","artifact-result-delivery","authority-driven-transformation","durable-artifact-materialization"],"status":"ADMITTED"}],"catalogType":"sda-platform-capability-catalog.v1","executionAuthority":{"target":"node","pinnedPlatformCommit":"716811046f52dd2a67f9ff308a50d755571cbbad","effectContext":{"module":"languages/typescript/runtimes/node/native-mechanic-primitives.mjs","export":"createGovernedEffectContext","digest":"sha256:1cc204869f0ce7b60ad03187d364db4a432b0b632ce4469a7cf37747d6a379d5"},"runtime":{"command":"node","args":["--input-type=module","-e","{source}"],"source":"import { createInterface } from ''node:readline'';\nimport { pathToFileURL } from ''node:url'';\nimport path from ''node:path'';\nconst rootUrl = relative => pathToFileURL(path.resolve(process.cwd(), relative)).href;\nconst { GraphTokenScheduler } = await import(rootUrl(''languages/typescript/runtimes/node/semantic-execution-graph/scheduler.js''));\nconst { evaluateExpression } = await import(rootUrl(''languages/typescript/runtimes/node/semantic-transformation-evaluator.mjs''));\nconst { createSynchronousSchemaAdmission } = await import(rootUrl(''languages/typescript/runtimes/node/schema-contract-admission-provider.mjs''));\nconst lines = createInterface({ input: process.stdin });\nconst stream = lines[Symbol.asyncIterator]();\nconst request = JSON.parse((await stream.next()).value);\nconst { plan, input: root, rootExecutionId } = request;\nconst physical = new Set(request.physicalCellIds);\nconst cells = new Map(plan.canonicalGraph.cells.map(cell => [cell.cellId, cell]));\nconst collections = new Map();\nasync function provider(input, context) {\n  if (physical.has(context.cellId)) {\n    console.log(JSON.stringify({ type: ''invoke-provider'', cellId: context.cellId, cellExecutionId: context.cellExecutionId, rootExecutionId, input }));\n    const reply = JSON.parse((await stream.next()).value);\n    if (reply.error) throw new Error(reply.error);\n    return { outcomeValue: reply.outcome };\n  }\n  const expression = context.configuration?.binding?.configuration?.expression ?? context.configuration;\n  if (expression && typeof expression.op === ''string'') {\n    try {\n      // The scheduler supplies the original Port input when it resumes a\n      // transformation operation. Decomposed expression cells use their\n      // enclosing expression input instead.\n      const entering = context.configuration?.kind === ''invoke-port'' ? input : context.decompositionInput ?? input;\n      const outcomeValue = evaluateExpression(expression, { input: entering, root });\n      if (outcomeValue === undefined) {\n        const scope = expression.op === ''path'' ? (expression.from ?? ''input'') : null;\n        if (scope === ''input'' || scope === ''root'') return { outcomeValue: false, outcomeVariant: ''FALSE'' };\n        throw new Error(''LEXICAL_BINDING_NOT_AVAILABLE_AT_CELL_ALTITUDE'');\n      }\n      if ([''map'', ''flat-map'', ''filter'', ''find'', ''some'', ''every''].includes(expression.op)) {\n        const occurrence = collections.get(context.cellId) ?? 0;\n        collections.set(context.cellId, occurrence + 1);\n        const source = expression.from ? evaluateExpression(expression.from, { input: entering, root }) : [];\n        return { outcomeValue, outcomeVariant: occurrence < (Array.isArray(source) ? source.length : 0) ? ''CONTINUE'' : ''STOP'' };\n      }\n      return { outcomeValue };\n    } catch {\n      return { outcomeValue: input, outcomeVariant: ''VALUE'' };\n    }\n  }\n  if (cells.get(context.cellId).execution.authorityId === ''mechanic:identity.v1'') return { outcomeValue: input, outcomeVariant: ''VALUE'' };\n  throw new Error(''UNDECLARED_EXECUTION_MECHANIC:'' + context.cellId);\n}\nconst authorities = new Map(plan.bindingAuthorities.map(authority => [authority.id, authority]));\nconst admission = createSynchronousSchemaAdmission(plan.contractCatalog);\nconst result = await new GraphTokenScheduler(plan.canonicalGraph, plan.realizationOverlay, {\n  providers: Object.fromEntries(plan.realizationOverlay.providerBindings.map(binding => [binding.providerProfileId, provider])),\n  rootExecutionId,\n  admitContract: (contractId, value) => admission.admits(contractId, value),\n  projectBinding: (id, input) => evaluateExpression(authorities.get(id).binding.configuration.expression, { input, root })\n}).execute(root);\nconsole.log(JSON.stringify({ type: ''result'', result }));\nlines.close();\nprocess.stdin.destroy();\r\n","sourceDigest":"sha256:485f3bd1225baf7846a84f100aac5ffbf43814853613a68db0494827be1e0db6","timeoutMilliseconds":60000,"maximumOutputBytes":16777216,"environment":{},"dependencies":[{"root":"sdaRoot","path":"languages/typescript/runtimes/node/semantic-execution-graph/scheduler.js","digest":"sha256:449f230dbbe7d5f1341b48d469ee134dd254a838b80138d6fac6762a4b8f05f8"},{"root":"sdaRoot","path":"languages/typescript/runtimes/node/semantic-transformation-evaluator.mjs","digest":"sha256:037366141a597af82c2e801226e351e4b84d97f67296c4ddcff4d52a1cf3e1b6"},{"root":"sdaRoot","path":"languages/typescript/runtimes/node/schema-contract-admission-provider.mjs","digest":"sha256:b8b8b60d0023d2ab0bff2d1239a3e19d73ebe2d4405b47cef006004b370eac5a"},{"root":"sdaRoot","path":"node_modules/ajv/package.json","digest":"sha256:1f9033ee5a6515e7d76938b7072941862d1ed228a6879cc7fe10cdeb75107989"}]},"contractAdmission":{"providerId":"ScenarioKernel.NodePlatform.Schema.JsonSchemaContractAdmission","module":"languages/typescript/runtimes/node/schema-contract-admission-provider.mjs","export":"createSynchronousSchemaAdmission","digest":"sha256:b8b8b60d0023d2ab0bff2d1239a3e19d73ebe2d4405b47cef006004b370eac5a"}}}',@object OUTPUT,@definition OUTPUT,@digest OUTPUT;
