_pk\nWHERE p.estate_model_pk=@estate_model_pk AND p.target_id=JSON_VALUE(@input,''$.target'')\nORDER BY m.mechanic_id;\n","rowLimit":2000,"relativeRoot":"embodiments","outcomeContract":"capability-embodiment-plan.v1","bindingType":"projected-consumer-application-binding.v3","candidateDisposition":"CANDIDATE","files":{"plan":"body/execution-plan.json","binding":"body/application-binding.json","fixtures":"evidence/fixture-authority.json","sourceMap":"evidence/source-map.json","conformance":"evidence/projection-conformance.json"}},"outcomeContract":"capability-embodiment-materialization.v1","bindingResolver":{"capabilityId":"resolve-provider-slot-bindings"},"authorityReader":{"defaultTarget":"node","profileAbsent":"PROFILE_PROVIDER_ABSENT","profileAmbiguous":"TARGET_PROVIDER_PROFILE_AMBIGUOUS"}}}]},"platformCapabilityId":"sda-embodiment-plan-port.v1","portId":"write-capability-embodiment-port"}',@object OUTPUT,@definition OUTPUT,@digest OUTPUT;
